const item = $input.first().json;
const parts = [];
if (item.query) parts.push(String(item.query).trim());
if (item.category) parts.push('#' + String(item.category).trim());
if (item.tags) {
  const tagList = String(item.tags).split(',').map(t => t.trim()).filter(Boolean);
  if (tagList.length) parts.push('tags:' + tagList.join('+'));
}
const allowedStatus = ['solved','unsolved','open','closed','archived','noreplies','single_user','public'];
if (item.status && allowedStatus.includes(String(item.status))) parts.push('status:' + item.status);
if (item.after) parts.push('after:' + String(item.after).trim());
if (item.before) parts.push('before:' + String(item.before).trim());
if (item.min_likes) parts.push('min_likes:' + String(item.min_likes).trim());
const allowedOrder = ['latest','likes','views','latest_topic'];
if (item.order && allowedOrder.includes(String(item.order))) parts.push('order:' + item.order);
const q = parts.join(' ');
const page = item.page && Number(item.page) > 0 ? Number(item.page) : 1;
return [{ q, page }];

const data = $input.first().json;
const topics = data.topics || [];
const posts = data.posts || [];
const categoryMap = new Map((data.categories || []).map(c => [c.id, { name: c.name, slug: c.slug }]));
const firstPostPerTopic = new Map();
for (const p of posts) {
  const existing = firstPostPerTopic.get(p.topic_id);
  if (!existing || (p.post_number && p.post_number < existing.post_number)) firstPostPerTopic.set(p.topic_id, p);
}
const baseUrl = 'https://community.n8n.io';
const buildQuery = $('Build Discourse Query').item.json;
const results = topics.map(t => {
  const cat = categoryMap.get(t.category_id);
  const firstPost = firstPostPerTopic.get(t.id);
  return {
    topic_id: t.id,
    title: t.fancy_title || t.title,
    url: baseUrl + '/t/' + t.slug + '/' + t.id,
    category: cat ? cat.name : null,
    tags: t.tags || [],
    solved: t.has_accepted_answer === true,
    closed: t.closed === true,
    archetype: t.archetype,
    reply_count: t.reply_count,
    posts_count: t.posts_count,
    views: t.views,
    like_count: t.like_count,
    created_at: t.created_at,
    last_posted_at: t.last_posted_at,
    excerpt: firstPost ? (firstPost.blurb || '').slice(0, 400) : null,
    matched_post_url: firstPost ? baseUrl + '/t/' + t.slug + '/' + t.id + '/' + firstPost.post_number : null,
    matched_username: firstPost ? firstPost.username : null
  };
});
return [{ total_returned: results.length, page: buildQuery.page, query: buildQuery.q, results }];
